// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(caller != address(this) && caller != address(c) && caller.code.length == 0);
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "deposit failed");
        uint256 balanceBefore = address(c).balance;
        uint256 userBalanceBefore = c.balances(caller);
        vm.prank(caller);
        c.withdraw();
        assertTrue(c.balances(caller) == 0 && address(c).balance == balanceBefore - userBalanceBefore);
    }
}
